const {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} = require("node:fs");
const path = require("node:path");
const { withFinalizedMod } = require("expo/config-plugins");

const GENERATED_NOTICE =
  "Generated by mobile/plugins/with-brand-assets.cjs from synchronized SHONGRE. assets.";

function findDirectory(root, name) {
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    if (!entry.isDirectory()) continue;
    const candidate = path.join(root, entry.name);
    if (entry.name === name) return candidate;
    const nested = findDirectory(candidate, name);
    if (nested) return nested;
  }
  return null;
}

function removeGeneratedAndroidIcons(resourceRoot) {
  const exactNames = new Set([
    "ic_launcher.webp",
    "ic_launcher.png",
    "ic_launcher_round.webp",
    "ic_launcher_round.png",
    "ic_launcher_foreground.webp",
    "ic_launcher_foreground.png",
    "ic_launcher_background.webp",
    "ic_launcher_background.png",
    "ic_launcher_monochrome.webp",
    "ic_launcher_monochrome.png",
  ]);
  for (const entry of readdirSync(resourceRoot, { withFileTypes: true })) {
    if (!entry.isDirectory() || !entry.name.startsWith("mipmap-")) continue;
    const directory = path.join(resourceRoot, entry.name);
    for (const file of readdirSync(directory)) {
      if (exactNames.has(file)) rmSync(path.join(directory, file));
    }
  }
  const generatedBackground = path.join(
    resourceRoot,
    "drawable",
    "ic_launcher_background.xml",
  );
  if (existsSync(generatedBackground)) rmSync(generatedBackground);
}

function mergeAndroidBrandColor(resourceRoot, sourceRoot) {
  const colorsPath = path.join(resourceRoot, "values", "colors.xml");
  const current = readFileSync(colorsPath, "utf8");
  const canonical = readFileSync(
    path.join(sourceRoot, "values", "colors.xml"),
    "utf8",
  );
  const color = canonical.match(
    /<color name="ic_launcher_background">[^<]+<\/color>/,
  )?.[0];
  if (!color) {
    throw new Error("Canonical Android launcher background color is missing.");
  }
  const withoutPrevious = current.replace(
    /\s*<color name="ic_launcher_background">[^<]+<\/color>/g,
    "",
  );
  const merged = withoutPrevious.replace(
    "</resources>",
    `  <!-- ${GENERATED_NOTICE} -->\n  ${color}\n</resources>`,
  );
  writeFileSync(colorsPath, merged);
}

function withIosBrandAssets(config) {
  return withFinalizedMod(config, [
    "ios",
    async (modConfig) => {
      const source = path.join(
        modConfig.modRequest.projectRoot,
        "assets/brand/native/ios/AppIcon.appiconset",
      );
      const assetCatalog = findDirectory(
        modConfig.modRequest.platformProjectRoot,
        "Images.xcassets",
      );
      if (!assetCatalog)
        throw new Error("Unable to locate iOS Images.xcassets.");
      const destination = path.join(assetCatalog, "AppIcon.appiconset");
      mkdirSync(destination, { recursive: true });
      const expoGeneratedIcon = path.join(
        destination,
        "App-Icon-1024x1024@1x.png",
      );
      if (existsSync(expoGeneratedIcon)) rmSync(expoGeneratedIcon);
      cpSync(source, destination, { recursive: true, force: true });
      return modConfig;
    },
  ]);
}

function withAndroidBrandAssets(config) {
  return withFinalizedMod(config, [
    "android",
    async (modConfig) => {
      const source = path.join(
        modConfig.modRequest.projectRoot,
        "assets/brand/native/android/res",
      );
      const destination = path.join(
        modConfig.modRequest.platformProjectRoot,
        "app/src/main/res",
      );
      removeGeneratedAndroidIcons(destination);
      for (const entry of readdirSync(source, { withFileTypes: true })) {
        if (entry.name === "values") continue;
        cpSync(
          path.join(source, entry.name),
          path.join(destination, entry.name),
          {
            recursive: true,
            force: true,
          },
        );
      }
      mergeAndroidBrandColor(destination, source);
      return modConfig;
    },
  ]);
}

module.exports = function withBrandAssets(config) {
  return withAndroidBrandAssets(withIosBrandAssets(config));
};
